def seed_database():
    print("Recreating database tables with image_url support...")
    # Drop existing tables and recreate cleanly with the new schema
    models.Base.metadata.drop_all(bind=engine)
    models.Base.metadata.create_all(bind=engine)

    session = SessionLocal()
    try:
        print(f"Preparing {len(RAW_ITEMS)} Indian food and drink items...")
        menu_objects = []
        for name, desc, price, cat, img in RAW_ITEMS:
            menu_objects.append(
                models.DBMenuItem(
                    name=name,
                    description=desc,
                    price=price,
                    category=cat,
                    image_url=img,
                    is_available=True
                )
            )

        session.add_all(menu_objects)
        session.commit()
        print(f"SUCCESS: Successfully inserted {len(menu_objects)} items into 'yummy.db'!")

        # Verify count
        total = session.query(models.DBMenuItem).count()
        print(f"Total menu items now in database: {total}")

        # Show breakdown by category
        from sqlalchemy import func
        breakdown = session.query(models.DBMenuItem.category, func.count(models.DBMenuItem.id)).group_by(models.DBMenuItem.category).all()
        print("\nCategory Breakdown:")
        for category, count in breakdown:
            print(f" - {category}: {count} items")

    finally:
        session.close()

if __name__ == "__main__":
    seed_database()

